Dictionary<string, Queue<DateTime>> windows = new Dictionary<string, Queue<DateTime>>();
bool Allow(string key, int limit, TimeSpan window, DateTime now)
{
    lock (windows)
    {
        if (!windows.TryGetValue(key, out Queue<DateTime>? q)) { q = new Queue<DateTime>(); windows[key] = q; }
        while (q.Count > 0 && now - q.Peek() > window) { q.Dequeue(); }
        if (q.Count >= limit) { return false; }
        q.Enqueue(now);
        return true;
    }
}

